struct Order { int id; int price; };
int main() {
  std::vector<Order> orders;
  for (int i = 0; i < 40; ++i)
    orders.push_back({i, 100});  // same price
  std::sort(orders.begin(), orders.end(),
    [](const Order& a, const Order& b) {
      return a.price >= b.price; });
  std::cout << "sorted " << orders.size();
}

std::stable_sort(orders.begin(), orders.end(),
  [](const Order& a, const Order& b) {
    return a.price > b.price; });
// sorted 40, first id 0

std::map<int, char> levels{
  {10, 'a'}, {20, 'b'}, {30, 'c'}};
int at_or_below(int k) {
  auto it = levels.lower_bound(k);
  --it;
  return it->first;
}
int main() {
  std::cout << at_or_below(25) << ' '
            << at_or_below(20) << '\n';
}

std::optional<int> at_or_below(int k) {
  auto it = levels.upper_bound(k);  // > k
  if (it == levels.begin())
    return std::nullopt;   // nothing <= k
  return std::prev(it)->first;
}
// 25 -> 20, 20 -> 20, 5 -> nullopt

